/* Reads up to SESSION_CHUNK bytes at offset into a NUL-terminated buffer. */
static char *read_chunk(int fd, off_t offset, size_t *len)
{
	char *buf;
	ssize_t n;
	size_t got = 0;

	buf = xmalloc(SESSION_CHUNK + 1);
	while (got < SESSION_CHUNK) {
		n = pread(fd, buf + got, SESSION_CHUNK - got, offset + (off_t)got);
		if (n < 0) {
			free(buf);
			return NULL;
		}
		if (n == 0)
			break;
		got += (size_t)n;
	}
	buf[got] = '\0';
	*len = got;
	return buf;
}

/*
 * The next complete line of buf from *p, NUL-terminated in place, or NULL.
 * A line cut by the end of the chunk is complete only at the end of file.
 */
static char *next_line(char **p, char *end, int at_eof)
{
	char *line, *nl;

	line = *p;
	if (line >= end)
		return NULL;
	nl = memchr(line, '\n', (size_t)(end - line));
	if (nl == NULL) {
		if (!at_eof)
			return NULL;
		*p = end;
		return line;
	}
	*nl = '\0';
	*p = nl + 1;
	return line;
}

static char *head_cwd(char *buf, size_t len, int at_eof)
{
	char *p = buf, *line, *cwd;

	while ((line = next_line(&p, buf + len, at_eof)) != NULL) {
		cwd = json_top_string(line, "cwd");
		if (cwd != NULL && cwd[0] == '/')
			return cwd;
		free(cwd);
	}
	return NULL;
}

/* The last relocatedCwd of a {"type":"relocated"} record in the chunk. */
static char *tail_relocated(char *buf, size_t len, int mid_line)
{
	char *p = buf, *line, *type, *cwd, *last = NULL;

	if (mid_line) {
		p = memchr(buf, '\n', len);
		if (p == NULL)
			return NULL;
		p++;
	}
	while ((line = next_line(&p, buf + len, 1)) != NULL) {
		if (strstr(line, "\"relocated\"") == NULL)
			continue;
		type = json_top_string(line, "type");
		cwd = NULL;
		if (type != NULL && strcmp(type, "relocated") == 0)
			cwd = json_top_string(line, "relocatedCwd");
		free(type);
		if (cwd != NULL && cwd[0] == '/') {
			free(last);
			last = cwd;
		} else {
			free(cwd);
		}
	}
	return last;
}

/*
 * The project a session file belongs to, read the way Claude Code reads it:
 * the last "relocated" record in the final SESSION_CHUNK bytes (written
 * when /cd or a worktree moved the session), otherwise the first cwd in
 * the first SESSION_CHUNK bytes. The first lines ("mode", snapshots) have
 * no cwd.
 */
char *session_file_cwd(const char *file)
{
	struct stat st;
	char *head, *tail, *cwd;
	size_t head_len, tail_len;
	off_t offset;
	int fd;

	fd = open(file, O_RDONLY);
	if (fd < 0)
		return NULL;
	if (fstat(fd, &st) != 0 || !S_ISREG(st.st_mode) ||
	    (head = read_chunk(fd, 0, &head_len)) == NULL) {
		close(fd);
		return NULL;
	}
	offset = st.st_size > SESSION_CHUNK ? st.st_size - SESSION_CHUNK : 0;
	if (offset == 0) {
		/* head_cwd cuts lines in place, so the tail gets its own copy. */
		tail = xmalloc(head_len + 1);
		memcpy(tail, head, head_len + 1);
		tail_len = head_len;
	} else {
		tail = read_chunk(fd, offset, &tail_len);
	}
	close(fd);
	cwd = NULL;
	if (tail != NULL)
		cwd = tail_relocated(tail, tail_len, offset > 0);
	if (cwd == NULL)
		cwd = head_cwd(head, head_len, (off_t)head_len >= st.st_size);
	free(head);
	free(tail);
	return cwd;
}

static int compare_names(const void *a, const void *b)
{
	return strcmp(*(char *const *)a, *(char *const *)b);
}

static int has_suffix(const char *s, const char *suffix)
{
	size_t n, m;

	n = strlen(s);
	m = strlen(suffix);
	return n >= m && strcmp(s + n - m, suffix) == 0;
}

/*
 * Sorted full paths of the entries in dir: regular .jsonl files when want_dir
 * is 0, real directories (never symlinks) when it is 1.
 */
static char **list_entries(const char *dir, int want_dir, size_t *count)
{
	DIR *d;
	struct dirent *e;
	struct stat st;
	char **names = NULL, *path;
	size_t n = 0, cap = 0;

	*count = 0;
	d = opendir(dir);
	if (d == NULL)
		return NULL;
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
			continue;
		if (!want_dir && !has_suffix(e->d_name, ".jsonl"))
			continue;
		path = xjoin(dir, e->d_name);
		if (lstat(path, &st) != 0 ||
		    (want_dir ? !S_ISDIR(st.st_mode) : !S_ISREG(st.st_mode))) {
			free(path);
			continue;
		}
		if (n == cap) {
			cap = cap ? cap * 2 : 16;
			names = xrealloc(names, cap * sizeof *names);
		}
		names[n++] = path;
	}
	closedir(d);
	if (n > 0)
		qsort(names, n, sizeof *names, compare_names);
	*count = n;
	return names;
}

static void free_entries(char **names, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		free(names[i]);
	free(names);
}

/* The first cwd found anywhere below dir, in name order. */
static char *any_cwd(const char *dir)
{
	char **names, *cwd = NULL;
	size_t count, i;

	names = list_entries(dir, 0, &count);
	for (i = 0; i < count && cwd == NULL; i++)
		cwd = session_file_cwd(names[i]);
	free_entries(names, count);
	if (cwd != NULL)
		return cwd;
	names = list_entries(dir, 1, &count);
	for (i = 0; i < count && cwd == NULL; i++)
		cwd = any_cwd(names[i]);
	free_entries(names, count);
	return cwd;
}

/*
 * The project path of a session directory. The top-level sessions start
 * where Claude Code was launched, so their first cwd is preferred, and one
 * that encodes to the directory name wins over the rest. Subagents may
 * start in a subdirectory, so their files are only a last resort. NULL when
 * no .jsonl has a cwd.
 */
char *session_dir_cwd(const char *dir)
{
	char **names, *cwd, *first = NULL, *encoded, *copy;
	const char *base;
	size_t count, i, len;

	copy = xstrdup(dir);
	len = strlen(copy);
	while (len > 1 && copy[len - 1] == '/')
		copy[--len] = '\0';
	base = strrchr(copy, '/');
	base = base != NULL ? base + 1 : copy;

	names = list_entries(dir, 0, &count);
	for (i = 0; i < count; i++) {
		cwd = session_file_cwd(names[i]);
		if (cwd == NULL)
			continue;
		encoded = path_encode(cwd);
		if (strcmp(encoded, base) == 0) {
			free(encoded);
			free(first);
			first = cwd;
			break;
		}
		free(encoded);
		if (first == NULL)
			first = cwd;
		else
			free(cwd);
	}
	free_entries(names, count);
	free(copy);
	if (first != NULL)
		return first;

	names = list_entries(dir, 1, &count);
	for (i = 0; i < count && first == NULL; i++)
		first = any_cwd(names[i]);
	free_entries(names, count);
	return first;
}

/* Sorted full paths of the regular <uuid>.jsonl files directly in dir. */
char **session_files(const char *dir, size_t *count)
{
	return list_entries(dir, 0, count);
}

void session_files_free(char **files, size_t count)
{
	free_entries(files, count);
}

void claude_paths_init(struct claude_paths *p)
{
	const char *env, *home;

	p->home = path_home();
	env = getenv("CLAUDE_CONFIG_DIR");
	if (env != NULL && env[0] != '\0') {
		p->config_dir = path_logical(env);
		if (p->config_dir == NULL)
			p->config_dir = xstrdup(env);
		p->config_file = xjoin(p->config_dir, ".claude.json");
	} else {
		home = p->home != NULL ? p->home : "/";
		p->config_dir = xjoin(home, ".claude");
		p->config_file = xjoin(home, ".claude.json");
	}
	p->projects_dir = xjoin(p->config_dir, "projects");
}

void claude_paths_free(struct claude_paths *p)
{
	free(p->home);
	free(p->config_dir);
	free(p->projects_dir);
	free(p->config_file);
	memset(p, 0, sizeof *p);
}

/* A content block of a message: {"type":"text","text":…} and the like. */
struct block {
	char *type;
	char *text;
};

/* What one line of a session file says, as far as csm -s needs it. */
struct line_facts {
	const char *line;
	char *type;
	char *timestamp;
	char *branch;
	char *custom_title;	/* customTitle of a custom-title record */
	char *ai_title;		/* aiTitle of an ai-title record */
	int is_meta;
	char *content;		/* message.content when it is a string */
	struct block *blocks;	/* message.content when it is an array */
	size_t block_count;
};

static char *token_string(const struct line_facts *f,
    const struct json_token *tok)
{
	return json_decode_string(f->line + tok->start + 1,
	    tok->end - tok->start - 2);
}

static void set_string(char **slot, const struct line_facts *f,
    const struct json_token *tok)
{
	free(*slot);
	*slot = tok->kind == JSON_STRING ? token_string(f, tok) : NULL;
}

static void collect_facts(const struct json_token *tok, void *ctx)
{
	struct line_facts *f = ctx;
	const struct json_seg *p = tok->path;
	struct block *b;
	size_t i;

	if (tok->is_key || tok->depth == 0 || p[0].key == NULL)
		return;
	if (tok->depth == 1) {
		if (strcmp(p[0].key, "type") == 0)
			set_string(&f->type, f, tok);
		else if (strcmp(p[0].key, "timestamp") == 0)
			set_string(&f->timestamp, f, tok);
		else if (strcmp(p[0].key, "gitBranch") == 0)
			set_string(&f->branch, f, tok);
		else if (strcmp(p[0].key, "customTitle") == 0)
			set_string(&f->custom_title, f, tok);
		else if (strcmp(p[0].key, "aiTitle") == 0)
			set_string(&f->ai_title, f, tok);
		else if (strcmp(p[0].key, "isMeta") == 0)
			f->is_meta = tok->kind == JSON_LITERAL &&
			    tok->end - tok->start == 4 &&
			    strncmp(f->line + tok->start, "true", 4) == 0;
		return;
	}
	if (strcmp(p[0].key, "message") != 0 || p[1].key == NULL ||
	    strcmp(p[1].key, "content") != 0)
		return;
	if (tok->depth == 2) {
		set_string(&f->content, f, tok);
		return;
	}
	if (tok->depth != 4 || p[2].key != NULL || p[3].key == NULL ||
	    tok->kind != JSON_STRING)
		return;
	while (f->block_count <= p[2].index) {
		i = f->block_count++;
		f->blocks = xrealloc(f->blocks, f->block_count * sizeof *b);
		f->blocks[i].type = NULL;
		f->blocks[i].text = NULL;
	}
	b = &f->blocks[p[2].index];
	if (strcmp(p[3].key, "type") == 0)
		set_string(&b->type, f, tok);
	else if (strcmp(p[3].key, "text") == 0)
		set_string(&b->text, f, tok);
}

static void facts_free(struct line_facts *f)
{
	size_t i;

	for (i = 0; i < f->block_count; i++) {
		free(f->blocks[i].type);
		free(f->blocks[i].text);
	}
	free(f->blocks);
	free(f->type);
	free(f->timestamp);
	free(f->branch);
	free(f->custom_title);
	free(f->ai_title);
	free(f->content);
}

static int is_space(int c)
{
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' ||
	    c == '\f';
}

static int blank(const char *s)
{
	while (is_space((unsigned char)*s))
		s++;
	return *s == '\0';
}

static int block_is(const struct block *b, const char *type)
{
	return b->type != NULL && strcmp(b->type, type) == 0;
}

/*
 * Whether a line is a message Claude Code counts: a user prompt with text,
 * an image or a document (tool results are not prompts), or an assistant
 * reply with text.
 */
static int counts_as_message(const struct line_facts *f)
{
	size_t i;
	int user;

	if (f->type == NULL)
		return 0;
	user = strcmp(f->type, "user") == 0;
	if (!user && strcmp(f->type, "assistant") != 0)
		return 0;
	if (user && f->is_meta)
		return 0;
	if (f->content != NULL)
		return user && !blank(f->content);
	for (i = 0; i < f->block_count; i++) {
		if (block_is(&f->blocks[i], "text") && (user ||
		    (f->blocks[i].text != NULL && !blank(f->blocks[i].text))))
			return 1;
		if (user && (block_is(&f->blocks[i], "image") ||
		    block_is(&f->blocks[i], "document")))
			return 1;
	}
	return 0;
}

/* The trimmed body of the first <tag>…</tag> in s, or NULL. */
static char *tag_body(const char *s, const char *tag)
{
	char *open, *close, *start, *end, *out;
	size_t n;

	n = strlen(tag);
	open = xmalloc(n + 3);
	close = xmalloc(n + 4);
	snprintf(open, n + 3, "<%s>", tag);
	snprintf(close, n + 4, "</%s>", tag);
	out = NULL;
	start = strstr(s, open);
	if (start != NULL) {
		start += n + 2;
		end = strstr(start, close);
		if (end != NULL) {
			while (start < end && is_space((unsigned char)*start))
				start++;
			while (end > start && is_space((unsigned char)end[-1]))
				end--;
			out = xmalloc((size_t)(end - start) + 1);
			memcpy(out, start, (size_t)(end - start));
			out[end - start] = '\0';
		}
	}
	free(open);
	free(close);
	return out;
}

/*
 * Text Claude Code itself puts into a prompt: a leading tag such as
 * <local-command-stdout>, or the note about an interrupted request.
 */
static int system_text(const char *s)
{
	static const char interrupted[] = "[Request interrupted by user";

	while (is_space((unsigned char)*s))
		s++;
	if (strncmp(s, interrupted, sizeof interrupted - 1) == 0)
		return strchr(s, ']') != NULL;
	if (s[0] != '<' || s[1] < 'a' || s[1] > 'z')
		return 0;
	for (s += 2; *s == '-' || *s == '_' || (*s >= 'a' && *s <= 'z') ||
	    (*s >= 'A' && *s <= 'Z') || (*s >= '0' && *s <= '9'); s++)
		;
	return *s == '>' || is_space((unsigned char)*s);
}

/* s cut to SESSION_PROMPT_MAX characters and "…", as Claude Code does. */
static char *prompt_cut(char *s)
{
	size_t i, chars = 0;
	char *out;

	for (i = 0; s[i] != '\0'; i++) {
		if (((unsigned char)s[i] & 0xc0) == 0x80)
			continue;
		if (chars++ == SESSION_PROMPT_MAX)
			break;
	}
	if (s[i] == '\0')
		return s;
	while (i > 0 && is_space((unsigned char)s[i - 1]))
		i--;
	out = xmalloc(i + 4);
	memcpy(out, s, i);
	memcpy(out + i, "\342\200\246", 4);
	free(s);
	return out;
}

/*
 * The prompt a text of a user message shows, or NULL when Claude Code
 * skips it. Newlines become spaces. A slash command shows as "/name args";
 * one without arguments is only a fallback (*fallback, if still NULL),
 * used when no real prompt follows. Claude Code also skips its own
 * built-in commands with arguments; csm does not know their names.
 */
char *session_prompt(const char *text, char **fallback)
{
	char *s, *name, *args, *out, *p;
	size_t n;

	s = xstrdup(text);
	for (p = s; *p != '\0'; p++)
		if (*p == '\n')
			*p = ' ';
	for (p = s; is_space((unsigned char)*p); p++)
		;
	n = strlen(p);
	while (n > 0 && is_space((unsigned char)p[n - 1]))
		n--;
	memmove(s, p, n);
	s[n] = '\0';
	out = NULL;
	if ((name = tag_body(s, "command-name")) != NULL) {
		args = tag_body(s, "command-args");
		if (args == NULL || args[0] == '\0') {
			if (*fallback == NULL)
				*fallback = xstrdup(name);
		} else {
			n = strlen(name) + strlen(args) + 2;
			out = xmalloc(n);
			snprintf(out, n, "%s %s", name, args);
		}
		free(name);
		free(args);
	} else if ((args = tag_body(s, "bash-input")) != NULL &&
	    args[0] != '\0') {
		n = strlen(args) + 3;
		out = xmalloc(n);
		snprintf(out, n, "! %s", args);
		free(args);
	} else {
		free(args);
		if (s[0] != '\0' && !system_text(s)) {
			out = s;
			s = NULL;
		}
	}
	free(s);
	return out != NULL ? prompt_cut(out) : NULL;
}

/* The first prompt of a user line, following Claude Code's rules. */
static char *line_prompt(const struct line_facts *f, char **fallback)
{
	char *prompt = NULL;
	size_t i;

	if (f->type == NULL || strcmp(f->type, "user") != 0 || f->is_meta)
		return NULL;
	if (f->content != NULL)
		return f->content[0] != '\0' ?
		    session_prompt(f->content, fallback) : NULL;
	for (i = 0; i < f->block_count; i++)
		if (block_is(&f->blocks[i], "tool_result"))
			return NULL;
	for (i = 0; i < f->block_count && prompt == NULL; i++)
		if (block_is(&f->blocks[i], "text") &&
		    f->blocks[i].text != NULL && f->blocks[i].text[0] != '\0')
			prompt = session_prompt(f->blocks[i].text, fallback);
	return prompt;
}

/* Whether s looks like a version: digits, letters, dots, "+" and "-". */
static int version_like(const char *s)
{
	size_t n;

	for (n = 0; s[n] != '\0'; n++)
		if (!((s[n] >= '0' && s[n] <= '9') ||
		    (s[n] >= 'a' && s[n] <= 'z') ||
		    (s[n] >= 'A' && s[n] <= 'Z') ||
		    s[n] == '.' || s[n] == '+' || s[n] == '-'))
			return 0;
	return n > 0 && n <= 32;
}

/* The last top-level "version" in a tail chunk; NULL when none. */
static char *tail_version(char *buf, size_t len, int mid_line)
{
	char *p = buf, *line, *v, *last = NULL;

	if (mid_line) {
		p = memchr(buf, '\n', len);
		if (p == NULL)
			return NULL;
		p++;
	}
	while ((line = next_line(&p, buf + len, 1)) != NULL) {
		if (strstr(line, "\"version\"") == NULL)
			continue;
		v = json_top_string(line, "version");
		if (v != NULL && version_like(v)) {
			free(last);
			last = v;
		} else {
			free(v);
		}
	}
	return last;
}

/*
 * The Claude Code version that wrote the newest session file: the last
 * top-level "version" in its final SESSION_CHUNK bytes, as message lines
 * carry it. Only <uuid>.jsonl files directly in the session directories
 * count. NULL when no file has one.
 */
char *session_claude_version(const char *projects_dir)
{
	struct stat st;
	char **dirs, **files, *newest = NULL, *buf, *version = NULL;
	size_t ndirs, nfiles, i, j, len;
	time_t best = 0;
	off_t offset;
	int fd;

	dirs = list_entries(projects_dir, 1, &ndirs);
	for (i = 0; i < ndirs; i++) {
		files = list_entries(dirs[i], 0, &nfiles);
		for (j = 0; j < nfiles; j++) {
			if (stat(files[j], &st) != 0 ||
			    (newest != NULL && st.st_mtime < best))
				continue;
			free(newest);
			newest = xstrdup(files[j]);
			best = st.st_mtime;
		}
		free_entries(files, nfiles);
	}
	free_entries(dirs, ndirs);
	if (newest == NULL)
		return NULL;
	fd = open(newest, O_RDONLY);
	free(newest);
	if (fd < 0)
		return NULL;
	if (fstat(fd, &st) == 0) {
		offset = st.st_size > SESSION_CHUNK ?
		    st.st_size - SESSION_CHUNK : 0;
		buf = read_chunk(fd, offset, &len);
		if (buf != NULL)
			version = tail_version(buf, len, offset > 0);
		free(buf);
	}
	close(fd);
	return version;
}

/*
 * Compares versions part by part, numbers by value ("2.1.10" is after
 * "2.1.9"), anything else byte by byte; <0, 0 or >0 as strcmp.
 */
int session_version_compare(const char *a, const char *b)
{
	unsigned long x, y;
	char *ea, *eb;

	while (*a != '\0' && *b != '\0') {
		if (*a >= '0' && *a <= '9' && *b >= '0' && *b <= '9') {
			x = strtoul(a, &ea, 10);
			y = strtoul(b, &eb, 10);
			if (x != y)
				return x < y ? -1 : 1;
			a = ea;
			b = eb;
			continue;
		}
		if (*a != *b)
			return (unsigned char)*a < (unsigned char)*b ? -1 : 1;
		a++;
		b++;
	}
	return (*a != '\0') - (*b != '\0');
}

/* Replaces *slot with a copy of value, unless value is missing or empty. */
static void keep_last(char **slot, const char *value)
{
	if (value == NULL || value[0] == '\0')
		return;
	free(*slot);
	*slot = xstrdup(value);
}

/*
 * What csm -s shows about one session file. The message count needs the
 * whole file, so the rest comes from the same pass: the first user or
 * assistant timestamp, the last gitBranch, the name and the first prompt.
 * The name is the last customTitle, else the last aiTitle; Claude Code
 * appends them again with every metadata write. Lines that
 * are not valid JSON (a last line still being written) are skipped.
 */
int session_info_read(const char *file, struct session_info *info)
{
	struct line_facts f;
	struct stat st;
	char *line = NULL, *fallback = NULL, *ai_title = NULL, *base;
	size_t cap = 0;
	ssize_t len;
	time_t t;
	FILE *fp;

	memset(info, 0, sizeof *info);
	fp = fopen(file, "r");
	if (fp == NULL)
		return -1;
	if (fstat(fileno(fp), &st) != 0) {
		fclose(fp);
		return -1;
	}
	info->modified = st.st_mtime;
	base = path_base(file);
	len = (ssize_t)strlen(base);
	if (len > 6 && strcmp(base + len - 6, ".jsonl") == 0)
		base[len - 6] = '\0';
	info->id = base;
	while ((len = getline(&line, &cap, fp)) > 0) {
		memset(&f, 0, sizeof f);
		f.line = line;
		if (json_scan(line, (size_t)len, collect_facts, &f) != 0) {
			facts_free(&f);
			continue;
		}
		if (counts_as_message(&f))
			info->messages++;
		if (info->started == 0 && f.timestamp != NULL &&
		    f.type != NULL && (strcmp(f.type, "user") == 0 ||
		    strcmp(f.type, "assistant") == 0) &&
		    parse_iso(f.timestamp, &t) == 0)
			info->started = t;
		keep_last(&info->branch, f.branch);
		keep_last(&info->title, f.custom_title);
		keep_last(&ai_title, f.ai_title);
		if (info->prompt == NULL)
			info->prompt = line_prompt(&f, &fallback);
		facts_free(&f);
	}
	free(line);
	fclose(fp);
	if (info->title == NULL)
		info->title = ai_title;
	else
		free(ai_title);
	if (info->prompt == NULL)
		info->prompt = fallback;
	else
		free(fallback);
	return 0;
}

void session_info_free(struct session_info *info)
{
	free(info->id);
	free(info->branch);
	free(info->title);
	free(info->prompt);
	memset(info, 0, sizeof *info);
}

/* Newest first, as /resume lists them; for qsort. */
int session_compare(const void *a, const void *b)
{
	const struct session_info *x = a, *y = b;

	if (x->modified != y->modified)
		return x->modified > y->modified ? -1 : 1;
	return strcmp(x->id, y->id);
}
